#!/usr/bin/env python3
"""Reference Bao slices for todoke's 16384-byte segments (PROTOCOL §7.4).

Usage: python3 -I generate_segment_slices.py PATH/TO/bao.py > segment_slices.json

PATH/TO/bao.py is the reference implementation from the Bao repository at
tag 0.13.1 (tests/bao.py; see README.md for the commit and SHA-256). It is
pure Python, including its BLAKE3, and independent of the Rust `bao` crate.
Its command-line parser (docopt) is not needed and is stubbed out.

Inputs use the Bao test-vector convention (tests/generate_input.py): a
4-byte little-endian counter starting at 1, truncated to the size.
"""

import importlib.util
import io
import json
import sys
import types

SEGMENT_LEN = 16384

# Sizes around chunk (1024) and segment (16384) boundaries, and multi-segment
# files whose trees have depth jumps and an unbalanced right edge.
SIZES = [
    0,
    1,
    1023,
    1024,
    1025,
    SEGMENT_LEN - 1,
    SEGMENT_LEN,
    SEGMENT_LEN + 1,
    2 * SEGMENT_LEN,
    2 * SEGMENT_LEN + 1,
    3 * SEGMENT_LEN + 1000,
    5 * SEGMENT_LEN,
    17 * SEGMENT_LEN + 1,
    33 * SEGMENT_LEN + 5000,
]

# Slices of files up to this size are recorded in full, not just hashed.
FULL_HEX_MAX = 1025


def load_bao(path):
    sys.modules["docopt"] = types.ModuleType("docopt")
    spec = importlib.util.spec_from_file_location("bao_reference", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def input_bytes(count):
    out = bytearray()
    i = 1
    while len(out) < count:
        out += i.to_bytes(4, "little")[: count - len(out)]
        i += 1
    return bytes(out)


def main():
    if len(sys.argv) != 2:
        sys.exit("usage: generate_segment_slices.py PATH/TO/bao.py")
    bao = load_bao(sys.argv[1])
    files = []
    for size in SIZES:
        content = input_bytes(size)
        encoded, root = bao.bao_encode(content)
        count = 1 if size == 0 else (size + SEGMENT_LEN - 1) // SEGMENT_LEN
        segments = []
        for index in range(count):
            start = index * SEGMENT_LEN
            length = min(SEGMENT_LEN, size - start)
            out = io.BytesIO()
            bao.bao_slice(io.BytesIO(encoded), out, start, length)
            data = out.getvalue()
            # Check the slice with the reference decoder, too.
            decoded = io.BytesIO()
            bao.bao_decode_slice(io.BytesIO(data), decoded, root, start, length)
            assert decoded.getvalue() == content[start : start + length]
            segment = {
                "index": index,
                "start": start,
                "len": length,
                "slice_len": len(data),
                "slice_blake3_hex": bao.bao_hash(io.BytesIO(data)).hex(),
            }
            if size <= FULL_HEX_MAX:
                segment["slice_hex"] = data.hex()
            segments.append(segment)
        files.append(
            {
                "size": size,
                "root_hex": bytes(root).hex(),
                "encoded_len": len(encoded),
                "segments": segments,
            }
        )
    document = {
        "_comment": (
            "Generated by generate_segment_slices.py from the Bao 0.13.1 "
            "reference implementation (tests/bao.py). Inputs are a 4-byte "
            "little-endian counter starting at 1. slice_blake3_hex is the "
            "BLAKE3 hash of the complete combined slice for segment index "
            "start = index * 16384, len = min(16384, size - start)."
        ),
        "segment_len": SEGMENT_LEN,
        "files": files,
    }
    json.dump(document, sys.stdout, indent=2, sort_keys=True)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
